import { getNotificationPreference } from "@/app/lib/preferences"
import { toggleNotifications } from "@/app/actions"

export default function Home() {
  const userId = "default-user"
  const enabled = getNotificationPreference(userId)
  const toggleWithUser = toggleNotifications.bind(null, userId)

  return (
    <main>
      <h1>Settings</h1>
      <p>Notification preference is currently: <strong>{enabled ? "ON" : "OFF"}</strong></p>
      <form action={toggleWithUser}>
        <button type="submit">
          Turn notifications {enabled ? "off" : "on"}
        </button>
      </form>
    </main>
  )
}

